// Structural validation of the Finance Inbox Request Contract this
// workflow receives from the Intent Router (ADR-0008 Decision 1,
// docs/workflows/finance-inbox-contract.md). Re-validated defensively here
// -- this workflow could in principle be called directly, not only via the
// Router -- same posture as 11-handle-get-budget.json's own "Validate
// Handler Input", which this Handler is structurally identical to up to
// this point. No Handler-specific requirement beyond the shared contract
// shape: this is a read-only query against org-wide dashboard data (no
// per-user scoping -- eyan-ai-platform backend/src/services/finance-dashboard.service.ts),
// so no externalUserId is required, and no `period` is parsed out of
// rawText -- this workflow always reports the current period, same
// posture and same reasoning as 11-handle-get-budget.json.
const req = $json || {};
const reasons = [];

function requireNonEmptyString(field) {
  if (typeof req[field] !== 'string' || req[field].trim().length === 0) {
    reasons.push(`Missing/empty required field: ${field}.`);
  }
}

requireNonEmptyString('contractVersion');
requireNonEmptyString('workflowExecutionId');
requireNonEmptyString('workflowName');
requireNonEmptyString('channel');

if (typeof req.rawText !== 'string') {
  reasons.push('rawText must be a string (may be empty).');
}

if (!Array.isArray(req.attachments)) {
  reasons.push('attachments must be an array.');
}

return [{
  json: {
    valid: reasons.length === 0,
    reason: reasons.join(' '),
    contractVersion: req.contractVersion,
    workflowExecutionId: req.workflowExecutionId,
    workflowName: req.workflowName,
    channel: req.channel,
    externalUserId: req.externalUserId ?? null,
    externalMessageId: req.externalMessageId ?? null,
    rawText: typeof req.rawText === 'string' ? req.rawText : '',
    attachments: Array.isArray(req.attachments) ? req.attachments : [],
  },
}];

// Orchestration-layer rejection (malformed/incomplete envelope) -- not a
// Finance business decision, so this never asks a clarifying question --
// same posture as 11-handle-get-budget.json's own "Build Invalid Input
// Response". intent stays GET_DASHBOARD (not UNRECOGNIZED): the Router
// already classified this correctly before dispatching here.
const v = $json;

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: v.workflowExecutionId || 'unknown',
    status: 'error',
    intent: 'GET_DASHBOARD',
    message: "Sorry, I couldn't process that request. Please try again.",
    data: null,
    clarifyingQuestion: null,
  },
}];

// Maps the Eyan Finance Service API's GET /finance/service/dashboard
// response onto the Response Contract (ADR-0008 Decision 2). This is the
// SAME endpoint 11-handle-get-budget.json calls -- eyan-ai-platform's
// ADR-0024 built one dashboard endpoint sufficient for both GET_BUDGET (a
// narrow read of budget/remainingBudget) and GET_DASHBOARD (the full
// response), rather than two separate routes. Unlike that Handler, this one
// surfaces the full payload in `data` -- budget, totalExpenses,
// remainingBudget, categoryBreakdown, spendingTrend, recentExpenses -- and
// builds a readable multi-line `message` from period/budget/category/recent
// data. spendingTrend is deliberately left out of `message` (it is still
// present in `data` for a richer future front door) -- a 6-month list of
// mostly-zero historical totals does not answer "show me my spending
// dashboard for this month" as directly as the current period's own
// numbers do, and rendering a trend judgment ("spending is up/down") would
// be a business decision this node does not make. Purely read-only
// formatting of real API data -- no mutation, no business calculation
// (every number here is computed server-side by FinanceDashboardService;
// this node only formats strings already returned).
const context = $('Validate Handler Input').item.json;
const result = $json;

const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

function humanPeriod(period) {
  const parts = typeof period === 'string' ? period.split('-') : [];
  const year = Number(parts[0]);
  const month = Number(parts[1]);
  if (!Number.isFinite(year) || !Number.isFinite(month) || month < 1 || month > 12) return period;
  return `${MONTH_NAMES[month - 1]} ${year}`;
}

function errorResponse(message) {
  return [{
    json: {
      contractVersion: '1',
      workflowExecutionId: context.workflowExecutionId,
      status: 'error',
      intent: 'GET_DASHBOARD',
      message,
      data: null,
      clarifyingQuestion: null,
    },
  }];
}

if (result && result.error) {
  const message = String((result.error && result.error.message) || result.error);
  console.log(`[Validate Finance API Response] Finance API call failed: ${message}`);
  return errorResponse("Sorry, I couldn't load your dashboard right now. Please try again in a moment.");
}

if (!result || result.success !== true || !result.data) {
  console.log(`[Validate Finance API Response] Finance API returned an unexpected shape: ${JSON.stringify(result)}`);
  return errorResponse("Sorry, I couldn't load your dashboard right now. Please try again in a moment.");
}

const data = result.data;
const period = humanPeriod(data.period);
const lines = [`Dashboard for ${period}:`];

if (data.budget) {
  const remainingNum = Number(data.remainingBudget);
  const remainingText = Math.abs(remainingNum).toFixed(2);
  lines.push(remainingNum < 0
    ? `Spent $${data.totalExpenses} of your $${data.budget.monthlyLimit} budget -- $${remainingText} over budget.`
    : `Spent $${data.totalExpenses} of your $${data.budget.monthlyLimit} budget -- $${remainingText} left.`);
} else {
  lines.push(`Spent $${data.totalExpenses} so far -- no budget set for this period.`);
}

const categoryBreakdown = Array.isArray(data.categoryBreakdown) ? data.categoryBreakdown : [];
if (categoryBreakdown.length > 0) {
  lines.push('By category:');
  for (const row of categoryBreakdown) {
    lines.push(`- ${row.category}: $${row.total}`);
  }
}

const recentExpenses = Array.isArray(data.recentExpenses) ? data.recentExpenses : [];
if (recentExpenses.length > 0) {
  lines.push('Recent expenses:');
  for (const expense of recentExpenses) {
    const description = expense.description ? ` -- ${expense.description}` : '';
    lines.push(`- $${expense.amount} ${expense.category}${description}`);
  }
}

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: context.workflowExecutionId,
    status: 'success',
    intent: 'GET_DASHBOARD',
    message: lines.join('\n'),
    data: {
      period: data.period,
      budget: data.budget,
      totalExpenses: data.totalExpenses,
      remainingBudget: data.remainingBudget,
      categoryBreakdown,
      spendingTrend: Array.isArray(data.spendingTrend) ? data.spendingTrend : [],
      recentExpenses,
    },
    clarifyingQuestion: null,
  },
}];
